// =============================================================
// MonsterQuest: The Cheshire Protocol — world data
// 18 towns and villages of Cheshire, 19 routes, and 5 landmark
// sites, generated by deterministic factories + hand-set story.
// =============================================================
// Tile legend (see sprites.js): . grass , flowers = path w tallgrass
// T tree ~ water F fence S sign R roof B wall W window D door
// _ floor r rug C counter K shelf M machine t table X void
// b berry bush G rock c cave floor
"use strict";

// ---- deterministic RNG for map generation ----------------------
function mapHash(s) {
  let h = 2166136261;
  for (const c of s) { h ^= c.codePointAt(0); h = Math.imul(h, 16777619) >>> 0; }
  return h >>> 0;
}
function mapRng(seed) {
  let a = mapHash(seed);
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

