// ---- town factory ----------------------------------------------
// Standard town: street across row 6, buildings on rows 2-4 above it.
// cfg: { name, w, buildings:[{kind,slot}], exits:{N:col,S:col,E:true,W:true -> {map,x,y}},
//        pond, music, npcs, signText, seed }
function makeTown(id, cfg) {
  const w = cfg.w || 22, h = cfg.h || 16;
  const rnd = mapRng(id);
  const g = Array.from({ length: h }, (_, y) =>
    Array.from({ length: w }, (_, x) =>
      (y === 0 || y === h - 1 || x === 0 || x === w - 1) ? "T" : "."));
  const warps = {};
  const signs = {};
  const npcs = (cfg.npcs || []).slice();

  // main street
  for (let x = 2; x < w - 2; x++) g[6][x] = "=";
  // exits
  const E = cfg.exits || {};
  if (E.W) { g[6][0] = "="; g[6][1] = "="; warps["0,6"] = E.W; }
  if (E.E) { g[6][w - 1] = "="; g[6][w - 2] = "="; warps[(w - 1) + ",6"] = E.E; }
  if (E.N) { const c = E.N.col; for (let y = 0; y <= 6; y++) g[y][c] = "="; warps[c + ",0"] = E.N.to; }
  if (E.S) { const c = E.S.col; for (let y = 6; y < h; y++) g[y][c] = "="; warps[c + "," + (h - 1)] = E.S.to; }

  // buildings along the top; slots at x = 2 + slot*6 (4 wide)
  for (const b of cfg.buildings || []) {
    const sx = 2 + b.slot * 6;
    for (let y = 2; y <= 3; y++) for (let x = sx; x < sx + 4; x++) g[y][x] = "R";
    for (let x = sx; x < sx + 4; x++) g[4][x] = "B";
    g[4][sx + 2] = "W";
    if (b.door !== false) {
      g[4][sx + 1] = "D";
      g[5][sx + 1] = "=";
      warps[(sx + 1) + ",4"] = { map: b.interior, x: b.ix, y: b.iy, dir: "up" };
    }
  }

  // town sign on the street
  const signX = cfg.signX || 3;
  g[8][signX] = "S";
  signs[signX + ",8"] = [cfg.name.toUpperCase(), ...(cfg.signText || [])];

  // pond (fishing) bottom-right
  if (cfg.pond) {
    for (let y = h - 6; y <= h - 4; y++) for (let x = w - 8; x <= w - 4; x++) g[y][x] = "~";
  }
  // flowers
  for (let i = 0; i < 8; i++) {
    const x = 2 + Math.floor(rnd() * (w - 4)), y = 8 + Math.floor(rnd() * (h - 10));
    if (g[y][x] === ".") g[y][x] = ",";
  }
  // decor houses (no doors)
  for (const dx of cfg.decorHouses || []) {
    for (let y = 9; y <= 10; y++) for (let x = dx; x < dx + 4 && x < w - 1; x++) g[y][x] = "R";
    for (let x = dx; x < dx + 4 && x < w - 1; x++) { g[11][x] = "B"; }
    if (g[11][dx + 2]) g[11][dx + 2] = "W";
  }

  return {
    name: cfg.name.toUpperCase(), outdoor: true, music: cfg.music || "town",
    tiles: g.map((r) => r.join("")),
    warps, signs, npcs,
    fishing: cfg.fishing, hotSpring: cfg.hotSpring,
  };
}

// ---- route factory ---------------------------------------------
// Horizontal routes: w x 12, path row 6. Vertical: 12 x len, path col 6.
function makeRoute(id, cfg) {
  const horiz = cfg.dir !== "v";
  const w = horiz ? (cfg.len || 40) : 12;
  const h = horiz ? 12 : (cfg.len || 34);
  const rnd = mapRng(id);
  const g = Array.from({ length: h }, (_, y) =>
    Array.from({ length: w }, (_, x) =>
      (y === 0 || y === h - 1 || x === 0 || x === w - 1) ? "T" : "."));
  const warps = {};
  const signs = {};
  const npcs = (cfg.npcs || []).slice();
  const P = 6; // path row/col

  if (horiz) {
    for (let x = 0; x < w; x++) g[P][x] = "=";
    warps["0,6"] = cfg.A;
    warps[(w - 1) + ",6"] = cfg.B;
  } else {
    for (let y = 0; y < h; y++) g[y][P] = "=";
    warps["6,0"] = cfg.A;
    warps["6," + (h - 1)] = cfg.B;
  }

  // tall-grass bands crossing the path
  const bands = cfg.bands === undefined ? 3 : cfg.bands;
  const span = (horiz ? w : h) - 10;
  for (let i = 0; i < bands; i++) {
    const at = 5 + Math.floor(((i + 0.3 + rnd() * 0.5) / bands) * span);
    const bw = 3 + Math.floor(rnd() * 2);
    for (let d = 0; d < bw; d++) for (let s = -3; s <= 3; s++) {
      const x = horiz ? at + d : P + s;
      const y = horiz ? P + s : at + d;
      if (g[y] && g[y][x] && y > 0 && y < h - 1 && x > 0 && x < w - 1) g[y][x] = "w";
    }
  }
  // extra grass pockets off the path
  for (let i = 0; i < (cfg.pockets === undefined ? 3 : cfg.pockets); i++) {
    const cx = 3 + Math.floor(rnd() * (w - 8)), cy = 2 + Math.floor(rnd() * (h - 5));
    for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 3; dx++) {
      const x = cx + dx, y = cy + dy;
      if (g[y] && g[y][x] === "." && y > 0 && y < h - 1 && x > 0 && x < w - 1) g[y][x] = "w";
    }
  }
  // tree clusters (forest feel)
  for (let i = 0; i < (cfg.trees || 0); i++) {
    const cx = 2 + Math.floor(rnd() * (w - 6)), cy = 2 + Math.floor(rnd() * (h - 5));
    for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) {
      const x = cx + dx, y = cy + dy;
      if (g[y] && g[y][x] === "." && Math.abs((horiz ? y : x) - P) > 1) g[y][x] = "T";
    }
  }
  // water strip with fishing
  if (cfg.water) {
    for (let i = 1; i <= 2; i++) for (let s = 2; s < (horiz ? w : h) - 2; s++) {
      const x = horiz ? s : (cfg.water === "top" ? i : w - 1 - i);
      const y = horiz ? (cfg.water === "top" ? i : h - 1 - i) : s;
      g[y][x] = "~";
    }
  }
  // berries
  for (let i = 0; i < (cfg.berries === undefined ? 2 : cfg.berries); i++) {
    const x = 3 + Math.floor(rnd() * (w - 7)), y = 2 + Math.floor(rnd() * (h - 5));
    if (g[y][x] === "." ) g[y][x] = "b";
  }
  // sign
  const sx = horiz ? 3 : 3, sy = horiz ? 3 : 3;
  if (g[sy][sx] !== "=") { g[sy][sx] = "S"; signs[sx + "," + sy] = cfg.sign || ["ROUTE"]; }

  // trainers stand just off the path, facing it
  (cfg.trainers || []).forEach((tid, i) => {
    const off = i % 2 === 0 ? 1 : -1;
    const at = 6 + Math.floor(((i + 0.6) / (cfg.trainers.length)) * (span - 2));
    const x = horiz ? at : P + off;
    const y = horiz ? P + off : at;
    g[y][x] = ".";
    npcs.push({
      id: id + "_t" + i, x, y,
      dir: horiz ? (off === 1 ? "up" : "down") : (off === 1 ? "left" : "right"),
      sprite: TRAINERS[tid].sprite || "boy", type: "trainer", trainerId: tid,
    });
  });

  return {
    name: (cfg.sign ? cfg.sign[0] : id.toUpperCase()), outdoor: true, music: cfg.music || "route",
    tiles: g.map((r) => r.join("")),
    warps, signs, npcs,
    encounters: cfg.encounters, fishing: cfg.fishing,
  };
}

// ---- cave factory ----------------------------------------------
function makeCave(id, cfg) {
  const w = cfg.w || 26, h = cfg.h || 18;
  const rnd = mapRng(id);
  const g = Array.from({ length: h }, (_, y) =>
    Array.from({ length: w }, (_, x) =>
      (y === 0 || y === h - 1 || x === 0 || x === w - 1) ? "X" : "c"));
  const warps = {};
  // rock sprinkle
  for (let y = 2; y < h - 2; y++) for (let x = 2; x < w - 2; x++) {
    if (rnd() < (cfg.density || 0.16)) g[y][x] = "G";
  }
  // carve L corridors between all key points so everything connects
  const pts = [];
  for (const e of cfg.exits) {
    g[e.y][e.x] = "c";
    warps[e.x + "," + e.y] = e.to;
    pts.push([Math.min(w - 2, Math.max(1, e.x)), Math.min(h - 2, Math.max(1, e.y))]);
  }
  for (const p of cfg.pockets || []) pts.push([p.x, p.y]);
  const carve = (x, y) => { if (g[y] && g[y][x] === "G") g[y][x] = "c"; };
  for (let i = 1; i < pts.length; i++) {
    let [x0, y0] = pts[i - 1], [x1, y1] = pts[i];
    for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++) { carve(x, y0); carve(x, y0 + 1); }
    for (let y = Math.min(y0, y1); y <= Math.max(y0, y1); y++) { carve(x1, y); carve(x1 + 1, y); }
  }
  for (const p of cfg.pockets || []) { g[p.y][p.x] = "c"; }
  return {
    name: cfg.name, outdoor: false, music: cfg.music || "cave",
    encounterEverywhere: true,
    tiles: g.map((r) => r.join("")),
    warps, signs: {}, npcs: cfg.npcs || [],
    encounters: cfg.encounters,
  };
}

// ---- encounter table helper ------------------------------------
function enc(lo, hi, commons, uncommons, rares) {
  const t = [];
  for (const s of commons) t.push([s, lo, hi, 30]);
  for (const s of uncommons || []) t.push([s, lo, hi + 1, 14]);
  for (const s of rares || []) t.push([s, lo + 1, hi + 2, 4]);
  return { rate: 0.13, table: t };
}

// ---- trainers ---------------------------------------------------
const TRAINERS = {};
function T(id, name, party, payout, opts) {
  TRAINERS[id] = Object.assign({
    name,
    party,
    payout,
    intro: opts.intro || ["Let's battle!"],
    winMsg: opts.win || ["Well fought!"],
    after: opts.after || ["Keep training!"],
    sprite: opts.sprite,
  }, opts.badge ? { isLeader: true, badge: opts.badge } : {},
     opts.grunt ? { grunt: true } : {});
}

